param([string]$RepositoryRoot="C:\TSD Production Control Full")
$ErrorActionPreference="Stop";$taskName="TSD Production Control Sync";$legacy="TSD Production Control - Oracle Sync";$script=Join-Path $RepositoryRoot "apps\oracle-sync\scripts\agent-tick.ps1";if(-not(Test-Path -LiteralPath $script)){throw"Agent script not found: $script"};if(Get-ScheduledTask -TaskName $legacy -ErrorAction SilentlyContinue){Disable-ScheduledTask -TaskName $legacy|Out-Null};$workingDirectory=Join-Path $RepositoryRoot "apps\oracle-sync";$action=New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$script`"" -WorkingDirectory $workingDirectory;$trigger=New-ScheduledTaskTrigger -Once -At(Get-Date).AddMinutes(1) -RepetitionInterval(New-TimeSpan -Minutes 1) -RepetitionDuration(New-TimeSpan -Days 3650);$settings=New-ScheduledTaskSettingsSet -MultipleInstances IgnoreNew -RestartCount 2 -RestartInterval(New-TimeSpan -Minutes 1) -ExecutionTimeLimit(New-TimeSpan -Minutes 20) -StartWhenAvailable;Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Settings $settings -Description "Polls secure refresh commands every minute and performs one Oracle read-only snapshot at most every five minutes." -Force|Out-Null;Write-Output "Installed $taskName; disabled duplicate $legacy"
